insert into public.exercise_categories (code, name, description, display_order) values
  ('respiration', 'Respiration', 'Exercices de respiration et de contrôle du souffle', 1),
  ('echauffement', 'Échauffement', 'Routine d''échauffement de la bouche et du visage', 2),
  ('articulation', 'Articulation', 'Travail des sons difficiles, progression complète', 3),
  ('virelangues', 'Virelangues', 'Virelangues classés par niveau et par son', 4),
  ('lecture', 'Lecture à voix haute', 'Textes d''entraînement variés et annotés', 5),
  ('improvisation', 'Improvisation', 'Sujets de prise de parole spontanée', 6),
  ('simulation', 'Simulations réelles', 'Mises en situation professionnelles', 7)
insert into public.exercises (category_id, title, difficulty, duration_sec, instructions, content, target_skill) values
  ((select id from public.exercise_categories where code = 'respiration'), 'Respiration abdominale allongée', 'facile', 180, 'Inspirez lentement par le nez en gonflant le ventre (la main sur la poitrine ne bouge presque pas). Expirez lentement par la bouche en rentrant le ventre.', '{"objectif": "Ressentir le mouvement du diaphragme", "position": "Allongé sur le dos, une main sur le ventre, une sur la poitrine", "erreur_a_eviter": "Soulever les épaules ou la poitrine au lieu du ventre", "progression": "Passer de la position allongée à assise, puis debout, en gardant la même sensation", "repetitions": "1 série continue"}'::jsonb, 'respiration'),
  ((select id from public.exercise_categories where code = 'respiration'), 'Respiration 4-4-4', 'facile', 120, 'Inspirez sur 4 temps, retenez l''air 4 temps, expirez sur 4 temps.', '{"objectif": "Réguler et calmer la respiration avant de parler", "position": "Assis, dos droit", "erreur_a_eviter": "Bloquer les épaules pendant la rétention", "progression": "Allonger progressivement à 4-4-6 puis 4-4-8", "repetitions": "8 à 10 cycles"}'::jsonb, 'respiration'),
  ((select id from public.exercise_categories where code = 'respiration'), 'Expiration sur consonne continue (S)', 'facile', 60, 'Inspirez profondément, puis expirez en émettant un « ssss » continu, le plus régulier et le plus long possible, sans à-coups.', '{"objectif": "Contrôler la régularité de l''expiration", "position": "Debout, dos droit", "erreur_a_eviter": "Laisser le son faiblir puis remonter en volume (souffle irrégulier)", "progression": "Chronométrer la durée du son et essayer de l''allonger chaque semaine", "repetitions": "5 séries"}'::jsonb, 'respiration'),
  ((select id from public.exercise_categories where code = 'respiration'), 'Expiration sur consonne continue (F)', 'facile', 60, 'Même principe que l''exercice précédent avec un « ffff » continu et stable.', '{"objectif": "Renforcer le contrôle du flux d''air", "position": "Debout, dos droit", "erreur_a_eviter": "Serrer la mâchoire pendant l''exercice", "progression": "Alterner S et F sans reprendre son souffle entre les deux", "repetitions": "5 séries"}'::jsonb, 'respiration'),
  ((select id from public.exercise_categories where code = 'respiration'), 'Compter sur une seule expiration', 'facile', 120, 'Inspirez, puis comptez à voix haute le plus loin possible sur une seule expiration, sans forcer la voix ni accélérer artificiellement.', '{"objectif": "Apprendre à doser l''air sur la durée d''une phrase", "position": "Debout ou assis", "erreur_a_eviter": "Accélérer le débit pour « aller plus loin » : cela fausse l''exercice", "progression": "Noter le chiffre atteint chaque semaine et viser une progression régulière", "repetitions": "5 essais"}'::jsonb, 'respiration'),
  ((select id from public.exercise_categories where code = 'respiration'), 'Phrase longue sur une expiration', 'facile', 180, 'Choisissez une phrase de 15 à 20 mots. Dites-la entièrement sur une seule expiration, à un rythme naturel, sans épuiser complètement l''air.', '{"objectif": "Relier respiration et longueur de phrase réelle", "position": "Debout", "erreur_a_eviter": "Vider complètement les poumons (cela crispe la fin de phrase)", "progression": "Augmenter progressivement la longueur des phrases travaillées", "repetitions": "6 phrases différentes"}'::jsonb, 'respiration'),
  ((select id from public.exercise_categories where code = 'respiration'), 'Respiration en marchant', 'facile', 300, 'Inspirez sur 4 pas, expirez sur 4 pas, en gardant une respiration basse et calme.', '{"objectif": "Dissocier respiration automatique et respiration contrôlée", "position": "En marchant à allure normale", "erreur_a_eviter": "Respirer haut et court à cause du rythme de marche", "progression": "Essayer de parler à voix haute tout en maintenant ce rythme respiratoire", "repetitions": "1 séance"}'::jsonb, 'respiration'),
  ((select id from public.exercise_categories where code = 'respiration'), 'Reprise d''air discrète en lecture', 'facile', 180, 'Lisez un paragraphe en plaçant volontairement de courtes reprises d''air aux virgules, sans marquer de pause audible ni de bruit d''inspiration.', '{"objectif": "Apprendre à reprendre son souffle sans casser le rythme", "position": "Debout, texte en main", "erreur_a_eviter": "Inspirer bruyamment ou marquer un arrêt trop long", "progression": "Réduire progressivement le nombre de reprises nécessaires par phrase", "repetitions": "2 paragraphes"}'::jsonb, 'respiration'),
  ((select id from public.exercise_categories where code = 'respiration'), 'Voix projetée sans forcer', 'facile', 180, 'Prononcez une phrase courte en visant le mur, en poussant l''air depuis le ventre plutôt qu''en serrant la gorge.', '{"objectif": "Contrôler le volume grâce au souffle, pas à la gorge", "position": "Debout, face à un mur à 3-4 mètres", "erreur_a_eviter": "Forcer sur les cordes vocales (sensation de tension dans la gorge)", "progression": "Reculer progressivement la distance de la cible", "repetitions": "10 phrases"}'::jsonb, 'respiration'),
  ((select id from public.exercise_categories where code = 'respiration'), 'Stabilité vocale sur voyelle tenue', 'facile', 120, 'Tenez un « aaaa » à hauteur et volume constants aussi longtemps que possible, sans trembler ni varier.', '{"objectif": "Stabiliser la hauteur et le volume de la voix", "position": "Assis ou debout", "erreur_a_eviter": "Laisser la voix descendre en hauteur en fin de son", "progression": "Chronométrer et comparer la durée d''une semaine à l''autre", "repetitions": "5 essais"}'::jsonb, 'respiration');
insert into public.exercises (category_id, title, difficulty, duration_sec, instructions, content, target_skill) values
  ((select id from public.exercise_categories where code = 'echauffement'), 'Vibrations de lèvres (bruit de moteur)', 'facile', 60, 'Laissez vos lèvres vibrer librement en soufflant, comme un moteur qui tourne, sur des sons graves puis aigus.', '{"zone": "Lèvres"}'::jsonb, 'echauffement'),
  ((select id from public.exercise_categories where code = 'echauffement'), 'Étirement O / I', 'facile', 60, 'Alternez rapidement une bouche très arrondie (« O ») et une bouche très étirée (« I »), en exagérant le mouvement.', '{"zone": "Lèvres"}'::jsonb, 'echauffement'),
  ((select id from public.exercise_categories where code = 'echauffement'), 'Pointe de langue contre les dents', 'facile', 60, 'Passez la pointe de la langue derrière les dents du haut, puis du bas, puis faites le tour complet des dents dans les deux sens.', '{"zone": "Langue"}'::jsonb, 'echauffement'),
  ((select id from public.exercise_categories where code = 'echauffement'), 'Langue en pointe / langue plate', 'facile', 60, 'Tirez la langue en pointe fine, puis aplatissez-la largement, en alternant rapidement.', '{"zone": "Langue"}'::jsonb, 'echauffement'),
  ((select id from public.exercise_categories where code = 'echauffement'), 'Ouverture/fermeture contrôlée', 'facile', 60, 'Ouvrez lentement la mâchoire au maximum sans douleur, maintenez 2 secondes, puis refermez lentement.', '{"zone": "Mâchoire"}'::jsonb, 'echauffement'),
  ((select id from public.exercise_categories where code = 'echauffement'), 'Mouvements latéraux', 'facile', 30, 'Déplacez doucement la mâchoire inférieure de gauche à droite, comme une mastication lente.', '{"zone": "Mâchoire"}'::jsonb, 'echauffement'),
  ((select id from public.exercise_categories where code = 'echauffement'), 'Gonflage et dégonflage', 'facile', 60, 'Gonflez les deux joues d''air, faites-le passer d''une joue à l''autre, puis relâchez d''un coup.', '{"zone": "Joues"}'::jsonb, 'echauffement'),
  ((select id from public.exercise_categories where code = 'echauffement'), 'Grimaces exagérées', 'facile', 60, 'Enchaînez des expressions faciales exagérées (sourire large, bouche en cœur, sourcils levés) pour réveiller l''ensemble du visage.', '{"zone": "Muscles faciaux"}'::jsonb, 'echauffement'),
  ((select id from public.exercise_categories where code = 'echauffement'), 'BA-BA / PA-PA / TA-TA / KA-KA', 'facile', 120, 'Répétez chaque syllabe rapidement 10 fois, en articulant nettement, puis enchaînez les quatre séries sans pause.', '{"zone": "Alternance de sons"}'::jsonb, 'echauffement'),
  ((select id from public.exercise_categories where code = 'echauffement'), 'Bâillement contrôlé', 'facile', 60, 'Simulez un grand bâillement pour détendre l''arrière de la gorge et le voile du palais, 3 à 4 répétitions.', '{"zone": "Ouverture de bouche"}'::jsonb, 'echauffement');
insert into public.exercises (category_id, title, difficulty, duration_sec, instructions, content, target_skill) values
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation P / B', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "P / B", "isoles": "pa – pe – pi – po – pu   |   ba – be – bi – bo – bu", "syllabes": "pa-pa – pe-pe – pi-pi – po-po – pu-pu   |   ba-ba – be-be – bi-bi", "mots": "papa, pipe, bébé, robe, papier, bobine", "groupes": "un petit pain, une belle bague, un beau bébé", "phrase": "Paul prépare plusieurs petits pains pour le petit-déjeuner.", "phrase_rapide": "Paul prépare plusieurs petits pains, Paul prépare plusieurs petits pains."}'::jsonb, 'articulation_P_B'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation T / D', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "T / D", "isoles": "ta – te – ti – to – tu   |   da – de – di – do – du", "syllabes": "ta-ta – te-te – ti-ti – to-to – tu-tu   |   da-da – de-de – di-di", "mots": "table, toit, tortue, dodu, dindon, danseuse", "groupes": "une tortue têtue, un dindon dodu", "phrase": "Didon dîna, dit-on, du dos d''un dodu dindon.", "phrase_rapide": "Didon dîna, dit-on, du dos d''un dodu dindon, Didon dîna, dit-on..."}'::jsonb, 'articulation_T_D'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation K / G', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "K / G", "isoles": "ka – ke – ki – ko – ku   |   ga – ge – gi – go – gu", "syllabes": "ka-ka – ke-ke – ki-ki – ko-ko – ku-ku   |   ga-ga – gue-gue – gui-gui", "mots": "cachet, caqueter, gare, gâteau, guitare, kaki", "groupes": "un carquois cassé, un gros gâteau craquant", "phrase": "Combien coûtent ces quinze caisses de kiwis craquants ?", "phrase_rapide": "Ces caisses de kiwis craquants coûtent-elles cher, ces caisses de kiwis craquants ?"}'::jsonb, 'articulation_K_G'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation F / V', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "F / V", "isoles": "fa – fe – fi – fo – fu   |   va – ve – vi – vo – vu", "syllabes": "fa-fa – fe-fe – fi-fi – fo-fo – fu-fu   |   va-va – ve-ve – vi-vi", "mots": "farine, fauve, veste, voisin, vif, fauve", "groupes": "un fauve vif, une veste violette", "phrase": "Le ver vert va vers le verre vert en verre vert.", "phrase_rapide": "Le ver vert va vers le verre vert, le ver vert va vers le verre vert."}'::jsonb, 'articulation_F_V'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation S / Z', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "S / Z", "isoles": "sa – se – si – so – su   |   za – ze – zi – zo – zu", "syllabes": "sa-sa – se-se – si-si – so-so – su-su   |   za-za – ze-ze – zi-zi", "mots": "saucisson, sûre, cerise, zèbre, azur, gazeuse", "groupes": "six saucissons sûrs, un zèbre zélé", "phrase": "Ces cerises sont si sûres qu''on ne sait pas si c''en sont.", "phrase_rapide": "Ces cerises sont si sûres, ces cerises sont si sûres, ces cerises sont si sûres."}'::jsonb, 'articulation_S_Z'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation CH / J', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "CH / J", "isoles": "cha – che – chi – cho – chu   |   ja – je – ji – jo – ju", "syllabes": "cha-cha – che-che – chi-chi – cho-cho – chu-chu   |   ja-ja – je-je – ji-ji", "mots": "chasseur, chaussette, jardin, jaune, jeudi, chouette", "groupes": "un chasseur juché, une chouette jaune", "phrase": "Chouette chose que cette chose chouette, dit le chasseur au chien couchant.", "phrase_rapide": "Chouette chose, chose chouette, chouette chose, chose chouette."}'::jsonb, 'articulation_CH_J'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation R', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "R", "isoles": "ra – re – ri – ro – ru – ar – er – ir – or – ur", "syllabes": "ra-ra – re-re – ri-ri – ro-ro – ru-ru – rar – rer – rir", "mots": "rare, roue, rire, robuste, cravate, tracteur", "groupes": "trois rats gris, un rare roseau rouge", "phrase": "Trois gros rats gris rongent trois gros croûtons ronds dans trois gros trous.", "phrase_rapide": "Rat vit rôt, rôt tenta rat, rat mit patte à rôt, rôt brûla patte à rat."}'::jsonb, 'articulation_R'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation L', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "L", "isoles": "la – le – li – lo – lu – al – el – il – ol – ul", "syllabes": "la-la – le-le – li-li – lo-lo – lu-lu – lal – lel – lil", "mots": "lilas, livre, lune, salade, village, applaudir", "groupes": "Lili lit un livre, un lilas léger", "phrase": "Que lit Lili sous ces lilas-là ? Lili lit l''Iliade.", "phrase_rapide": "Lili lit sous les lilas, Lili lit sous les lilas, Lili lit sous les lilas."}'::jsonb, 'articulation_L'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation M / N', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "M / N", "isoles": "ma – me – mi – mo – mu   |   na – ne – ni – no – nu", "syllabes": "ma-ma – me-me – mi-mi – mo-mo – mu-mu   |   na-na – ne-ne – ni-ni", "mots": "maman, montagne, nature, nuage, mener, nommer", "groupes": "une montagne nue, un nuage magnifique", "phrase": "Natacha n''attacha pas son chat Pacha, qui s''échappa dans la nature.", "phrase_rapide": "Natacha n''attacha pas son chat Pacha, Natacha n''attacha pas son chat Pacha."}'::jsonb, 'articulation_M_N'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation TR / DR', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "TR / DR", "isoles": "tra – tre – tri – tro – tru   |   dra – dre – dri – dro – dru", "syllabes": "tra-tra – tre-tre – tri-tri – tro-tro – tru-tru", "mots": "train, tramway, trottoir, drapeau, dragon, drôle", "groupes": "un train tranquille, un drapeau drôle", "phrase": "Trois tortues trottaient sur trois toits très étroits, tirant un train tranquille.", "phrase_rapide": "Trois tortues trottaient sur trois toits, trois tortues trottaient sur trois toits."}'::jsonb, 'articulation_TR_DR'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation PR / BR', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "PR / BR", "isoles": "pra – pre – pri – pro – pru   |   bra – bre – bri – bro – bru", "syllabes": "pra-pra – pre-pre – pri-pri – pro-pro – pru-pru", "mots": "prendre, prudent, printemps, bras, brosse, brave", "groupes": "un printemps précoce, un bras brave", "phrase": "Le prudent primeur prépare précieusement ses primeurs de printemps.", "phrase_rapide": "Le prudent primeur prépare ses primeurs, le prudent primeur prépare ses primeurs."}'::jsonb, 'articulation_PR_BR'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation CR / GR', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "CR / GR", "isoles": "cra – cre – cri – cro – cru   |   gra – gre – gri – gro – gru", "syllabes": "cra-cra – cre-cre – cri-cri – cro-cro – cru-cru", "mots": "cravate, crocodile, gravier, grand, gris, croquant", "groupes": "un crocodile gris, un gravier croquant sous les pas", "phrase": "Le grand crocodile gris croque un croûton croustillant sur le gravier.", "phrase_rapide": "Le grand crocodile gris croque, le grand crocodile gris croque un croûton."}'::jsonb, 'articulation_CR_GR'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation CL / GL', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "CL / GL", "isoles": "cla – cle – cli – clo – clu   |   gla – gle – gli – glo – glu", "syllabes": "cla-cla – cle-cle – cli-cli – clo-clo – clu-clu", "mots": "clair, cloche, classe, glace, glissade, aigle", "groupes": "une cloche claire, une glace glissante", "phrase": "La cloche claire annonce la classe, sous un ciel clair et glacial.", "phrase_rapide": "La cloche claire annonce la classe, la cloche claire annonce la classe."}'::jsonb, 'articulation_CL_GL'),
  ((select id from public.exercise_categories where code = 'articulation'), 'Articulation PL / BL', 'intermediaire', 300, 'Progressez dans l''ordre : sons isolés, syllabes, mots, groupes de mots, phrase, puis phrase rapide. Ne passez à l''étape suivante que si la précédente est fluide.', '{"sons": "PL / BL", "isoles": "pla – ple – pli – plo – plu   |   bla – ble – bli – blo – blu", "syllabes": "pla-pla – ple-ple – pli-pli – plo-plo – plu-plu", "mots": "pluie, place, plateau, blanc, bleu, table", "groupes": "un plateau blanc, une place bleue", "phrase": "Sous la pluie, la place blanche devient un plateau bleu et pâle.", "phrase_rapide": "Sous la pluie, la place blanche, sous la pluie, la place blanche."}'::jsonb, 'articulation_PL_BL');
insert into public.exercises (category_id, title, difficulty, duration_sec, instructions, content, target_skill) values
  ((select id from public.exercise_categories where code = 'virelangues'), 'Ton thé t''a-t-il ôté ta toux ?', 'facile', 90, 'Méthode en 6 étapes : très lentement, lentement sans erreur, vitesse normale, légèrement plus rapide, vitesse maximale précise, puis 3 répétitions sans erreur.', '{"texte": "Ton thé t''a-t-il ôté ta toux ?", "son": "T/D", "niveau": 1, "methode_etapes": 6}'::jsonb, 'articulation_T_D'),
  ((select id from public.exercise_categories where code = 'virelangues'), 'As-tu été à Tahiti ?', 'facile', 90, 'Méthode en 6 étapes : très lentement, lentement sans erreur, vitesse normale, légèrement plus rapide, vitesse maximale précise, puis 3 répétitions sans erreur.', '{"texte": "As-tu été à Tahiti ?", "son": "T", "niveau": 1, "methode_etapes": 6}'::jsonb, 'articulation_T'),
  ((select id from public.exercise_categories where code = 'virelangues'), 'Suis-je bien chez ce cher Serge ?', 'facile', 90, 'Méthode en 6 étapes : très lentement, lentement sans erreur, vitesse normale, légèrement plus rapide, vitesse maximale précise, puis 3 répétitions sans erreur.', '{"texte": "Suis-je bien chez ce cher Serge ?", "son": "S/CH", "niveau": 1, "methode_etapes": 6}'::jsonb, 'articulation_S_CH'),
  ((select id from public.exercise_categories where code = 'virelangues'), 'Le loup va vite au bois.', 'facile', 90, 'Méthode en 6 étapes : très lentement, lentement sans erreur, vitesse normale, légèrement plus rapide, vitesse maximale précise, puis 3 répétitions sans erreur.', '{"texte": "Le loup va vite au bois.", "son": "L/V", "niveau": 1, "methode_etapes": 6}'::jsonb, 'articulation_L_V'),
  ((select id from public.exercise_categories where code = 'virelangues'), 'Poisson sans boisson est poison.', 'facile', 90, 'Méthode en 6 étapes : très lentement, lentement sans erreur, vitesse normale, légèrement plus rapide, vitesse maximale précise, puis 3 répétitions sans erreur.', '{"texte": "Poisson sans boisson est poison.", "son": "S", "niveau": 1, "methode_etapes": 6}'::jsonb, 'articulation_S'),
  ((select id from public.exercise_categories where code = 'virelangues'), 'Piano ou violon, voilà mon dilemme.', 'facile', 90, 'Méthode en 6 étapes : très lentement, lentement sans erreur, vitesse normale, légèrement plus rapide, vitesse maximale précise, puis 3 répétitions sans erreur.', '{"texte": "Piano ou violon, voilà mon dilemme.", "son": "P/V", "niveau": 1, "methode_etapes": 6}'::jsonb, 'articulation_P_V'),
  ((select id from public.exercise_categories where code = 'virelangues'), 'Douze douches douces dans la salle de bain.', 'facile', 90, 'Méthode en 6 étapes : très lentement, lentement sans erreur, vitesse normale, légèrement plus rapide, vitesse maximale précise, puis 3 répétitions sans erreur.', '{"texte": "Douze douches douces dans la salle de bain.", "son": "D", "niveau": 1, "methode_etapes": 6}'::jsonb, 'articulation_D'),
  ((select id from public.exercise_categories where code = 'virelangues'), 'Seize chaises sèches sèchent au soleil.', 'facile', 90, 'Méthode en 6 étapes : très lentement, lentement sans erreur, vitesse normale, légèrement plus rapide, vitesse maximale précise, puis 3 répétitions sans erreur.', '{"texte": "Seize chaises sèches sèchent au soleil.", "son": "S/CH", "niveau": 1, "methode_etapes": 6}'::jsonb, 'articulation_S_CH'),
