insert into public.exercises (category_id, title, difficulty, duration_sec, instructions, content, target_skill) values
  ((select id from public.exercise_categories where code = 'lecture'), '1. La ville au réveil', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "La ville s''éveille lentement. / Les premiers volets s''ouvrent, / un à un, / sur des rues encore silencieuses. // Le boulanger allume sa devanture, / le facteur charge son vélo, / et déjà quelques passants pressés traversent la place. // Rien ne semble annoncer l''agitation qui, dans une heure, ↑ envahira chaque avenue. //", "type": "Narration", "objectif": "Articulation et rythme régulier"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '2. Le vieux pont', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Le vieux pont de pierre enjambe la rivière depuis trois siècles. / Ses arches usées portent encore les traces des crues anciennes, / et la mousse verte s''accroche aux joints fatigués. // On raconte / que les pêcheurs du village s''y retrouvaient chaque matin, / avant que le pont de fer ne le remplace, ↓ plus bas, dans la vallée. //", "type": "Description", "objectif": "Pauses et respiration"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '3. Prise de parole en réunion', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Mesdames, Messieurs, / je vous remercie de votre présence ce matin. // Nous allons aborder trois points essentiels : / le calendrier du projet, / les ressources disponibles, / et les risques identifiés. // Je vous propose de commencer ↑ par un état des lieux rapide de la situation actuelle. //", "type": "Discours", "objectif": "Débit maîtrisé, articulation professionnelle"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '4. Rapport professionnel', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Le chiffre d''affaires du dernier trimestre s''établit à deux millions trois cent mille euros, / soit une progression de sept pour cent par rapport à la période précédente. // Cette croissance s''explique principalement / par l''ouverture de deux nouveaux marchés / et par une réduction des coûts de production. //", "type": "Texte professionnel", "objectif": "Précision et clarté"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '5. Se présenter en entretien', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Bonjour, / je m''appelle [votre prénom]. // Je viens de terminer une formation en [domaine], / au cours de laquelle j''ai particulièrement développé mes compétences en [compétence]. // Ce qui m''intéresse aujourd''hui, / c''est de mettre ces compétences au service d''un projet concret ↑ comme celui que vous proposez. //", "type": "Présentation personnelle", "objectif": "Fluidité et confiance"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '6. Le cycle de l''eau', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "L''eau des océans s''évapore sous l''effet de la chaleur solaire. // Cette vapeur s''élève, / se refroidit en altitude / et se condense en fines gouttelettes qui forment les nuages. // Lorsque ces gouttelettes deviennent trop lourdes, / elles retombent sous forme de pluie ↓ et rejoignent, tôt ou tard, la mer. //", "type": "Texte scientifique", "objectif": "Vocabulaire technique, articulation"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '7. Édition spéciale', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Bonsoir à tous. / Ce soir, / trois informations à retenir. // D''abord, / la situation économique reste stable / malgré les incertitudes internationales. // Ensuite, / une nouvelle ligne de transport ouvrira dès la semaine prochaine. // Enfin, / la météo annonce un temps clément ↑ pour tout le week-end. //", "type": "Texte journalistique", "objectif": "Débit rapide contrôlé, intonation journalistique"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '8. Le premier jour', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Le premier jour est toujours le plus incertain. // On doute, / on hésite, / on se demande si l''on est à la hauteur. // Et pourtant, / c''est précisément ce premier pas / qui rend tout le reste possible. // Ne cherchez pas la perfection dès le départ : ↑ cherchez seulement à commencer. //", "type": "Texte motivant", "objectif": "Expressivité, variations de rythme"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '9. Deux collègues', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "— Tu as vu l''heure ? / La réunion commence dans dix minutes. // — Je sais, / je sais, / j''arrive tout de suite. // — Tu as les documents ? // — Oui, / ils sont là, / dans le dossier bleu. // — Parfait, ↑ alors on y va. //", "type": "Dialogue", "objectif": "Alternance de voix, rythme naturel"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '10. Le vocabulaire de la précision', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "L''anesthésiste, / après avoir consulté l''électrocardiogramme, / a recommandé une surveillance postopératoire rigoureuse. // Le protocole thérapeutique prévoit une réévaluation systématique / toutes les quarante-huit heures, ↓ afin d''anticiper toute complication éventuelle. //", "type": "Vocabulaire difficile", "objectif": "Mots difficiles, articulation fine"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '11. La montagne au petit matin', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "À cette altitude, / l''air se fait plus rare et plus vif. // Le sommet, / encore enveloppé de brume, / se dévoile lentement à mesure que le soleil se lève, / dessinant des ombres longues sur la neige fraîche, / tandis que le silence, ↑ presque total, / n''est troublé que par le crissement des pas. //", "type": "Description", "objectif": "Souffle long, phrases amples"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '12. Le premier client', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "— Bonjour, / je cherche quelque chose de simple et efficace. // — Bien sûr, / laissez-moi vous montrer nos modèles les plus demandés. // — Celui-ci me plaît beaucoup. // — Excellent choix, ↑ il est disponible en trois couleurs. //", "type": "Dialogue", "objectif": "Débit conversationnel"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '13. Une décision difficile', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Il resta longtemps silencieux, / pesant chaque mot avant de parler. // Ce n''était pas une décision qu''on prenait à la légère, / et il le savait. // Finalement, ↓ après un dernier regard vers la fenêtre, / il se leva / et annonça sa décision d''une voix calme et posée. //", "type": "Narration", "objectif": "Intonation, gravité maîtrisée"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '14. Présentation de projet en 2 minutes', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Notre projet répond à un besoin simple : / gagner du temps dans les tâches répétitives. // Concrètement, / notre solution automatise trois étapes clés / que nos utilisateurs effectuaient auparavant manuellement. // Les premiers retours sont très positifs, ↑ avec un gain de temps mesuré de trente pour cent. //", "type": "Discours", "objectif": "Débit soutenu et structuré"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '15. Le marché du samedi', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Sur la place, / les étals se dressent dès l''aube. // Les couleurs des fruits se mêlent à celles des légumes, / les cageots s''empilent, / et les vendeurs interpellent les passants d''une voix forte et chaleureuse. // L''odeur du pain chaud ↑ se mêle à celle du café fraîchement moulu. //", "type": "Description", "objectif": "Rythme vivant, vocabulaire concret"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '16. Argumenter une opinion', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Je pense sincèrement / que cette approche mérite d''être reconsidérée. // D''abord, / parce qu''elle repose sur des données anciennes. // Ensuite, / parce que le contexte a profondément changé. // Et enfin, ↑ parce qu''une alternative plus efficace existe déjà. //", "type": "Discours", "objectif": "Fermeté, articulation soutenue"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '17. Une invention méconnue', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "On attribue souvent cette invention à un seul ingénieur, / alors qu''elle résulte en réalité du travail conjoint de plusieurs équipes. // Les premiers essais, / menés dans les années soixante, / se soldèrent par des échecs répétés, ↓ avant qu''une avancée décisive ne permette enfin la mise au point du prototype final. //", "type": "Texte scientifique", "objectif": "Rythme narratif, précision des faits"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '18. Le dernier train', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Il courait / sans regarder derrière lui. // Les quais défilaient, / de plus en plus vite, / et le sifflet du train résonnait déjà. // Encore quelques mètres, / encore quelques secondes, ↑ et les portes se refermèrent / juste au moment où il sautait à bord. //", "type": "Narration", "objectif": "Tension narrative, variations de vitesse"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '19. Bilan de fin d''année', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Cette année aura été marquée par plusieurs avancées majeures. // Nous avons renforcé notre équipe, / lancé deux nouveaux produits / et amélioré significativement notre satisfaction client. // Pour l''année prochaine, ↑ nous concentrerons nos efforts sur trois priorités claires. //", "type": "Texte professionnel", "objectif": "Débit posé et structuré"}'::jsonb, 'fluidite'),
  ((select id from public.exercise_categories where code = 'lecture'), '20. Un dernier conseil', 'intermediaire', 150, 'Lisez à voix haute en respectant les indications de pause et d’intonation.', '{"texte": "Ce que vous venez de lire n''est qu''un point de départ. // La vraie progression se joue dans la répétition, / jour après jour, / bien plus que dans la théorie. // Alors ne cherchez pas la performance immédiate : ↑ cherchez la régularité, / et la clarté suivra naturellement. //", "type": "Texte motivant", "objectif": "Expressivité, conclusion marquante"}'::jsonb, 'fluidite');
